<script>
import{onMount}from'svelte';import{page}from'$app/state';const venueId=$derived(page.params.venueid);
let tournamentState=$state(/** @type {any} */ (null)),error=$state('');
/** @type {ReturnType<typeof setInterval> | null} */
let interval = null;
let remainingMs=$state(0);
async function refresh(){try{const r=await fetch('/api/tournament/'+venueId+'?public=1',{cache:'no-store'});if(!r.ok)throw new Error('Unable to load the tournament display.');const d=await r.json();tournamentState=d.state;remainingMs=tournamentState?.remainingMs??0;error='';}catch(e){error=e instanceof Error?e.message:'Connection lost.';}}
/** @param {number} ms */
function clock(ms){const s=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');}
onMount(() => {
	refresh();
	interval = setInterval(refresh, 1000);
	return () => {
		if (interval !== null) clearInterval(interval);
	};
});
</script>
<svelte:head><title>Tournament TV display</title><meta name="viewport" content="width=device-width,initial-scale=1"/></svelte:head>
<div class="display">{#if error}<div class="connection-error">{error}</div>{/if}{#if tournamentState}<header><span>LIVE TOURNAMENT</span><h1>{tournamentState.venueName||'Venue '+venueId}</h1></header><section class="hero"><div class="game">{tournamentState.currentGame}</div><div class="timer">{clock(remainingMs)}</div><div class="blinds">{tournamentState.blinds}</div><div class="progress">{tournamentState.running?'IN PLAY':'PAUSED'}</div></section><section class="next"><div><small>NEXT LEVEL</small><strong>{tournamentState.nextGame}</strong><span>{tournamentState.nextBlinds}</span></div><div><small>PLAYERS</small><strong>{tournamentState.activePlayerCount}</strong></div></section>{#if tournamentState.players?.length}<section class="players"><h2>Players</h2><div class="player-grid">{#each tournamentState.players as player,index (player.name+index)}<div class:out={player.eliminated}><span>{index+1}</span><strong>{player.name}</strong>{#if player.eliminated}<small>OUT · {player.position??''}</small>{/if}</div>{/each}</div></section>{/if}{:else}<div class="waiting"><h1>Waiting for tournament</h1><p>Open the admin app and start the tournament.</p></div>{/if}</div>
<style>
:global(*){box-sizing:border-box}:global(body){margin:0;background:#101214;color:#f4f4f1;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.display{min-height:100vh;padding:3vh 4vw;background:radial-gradient(circle at top,rgba(255,255,255,.07),transparent 36rem),#101214;display:flex;flex-direction:column;gap:3vh}header{text-align:center}header span,small{color:#9aa1a8;font-size:clamp(.7rem,1vw,1rem);font-weight:800;letter-spacing:.16em}header h1{font-size:clamp(1.3rem,3vw,2.5rem);margin:.4rem 0}.hero{flex:1;min-height:42vh;display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px solid #343a40;border-radius:24px;background:#181b1f;padding:3vh 2vw}.game{color:#c4a36a;font-size:clamp(1.2rem,3vw,2.5rem);font-weight:800;letter-spacing:.12em}.timer{font-size:clamp(5rem,20vw,16rem);font-weight:800;letter-spacing:-.08em;line-height:1.05;font-variant-numeric:tabular-nums}.blinds{font-size:clamp(2rem,6vw,5rem);font-weight:700}.progress{margin-top:1.5rem;color:#9aa1a8;font-weight:800;letter-spacing:.2em}.next{display:flex;justify-content:center;gap:clamp(3rem,12vw,12rem);padding:1.5rem;border-bottom:1px solid #343a40}.next div{display:flex;flex-direction:column;align-items:center;gap:.35rem}.next strong{font-size:clamp(1.5rem,3vw,3rem)}.next span{color:#aeb5bb}.players h2{text-align:center;font-size:clamp(1.2rem,2vw,2rem)}.player-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.5rem}.player-grid>div{display:flex;gap:.8rem;align-items:center;padding:.8rem 1rem;background:#181b1f;border-radius:8px}.player-grid span{color:#c4a36a;font-weight:800}.player-grid small{margin-left:auto;letter-spacing:0}.player-grid .out{opacity:.45;text-decoration:line-through}.waiting{margin:auto;text-align:center}.connection-error{position:fixed;top:10px;right:10px;color:#ffb2b2;background:#401c1c;padding:8px 12px;border-radius:8px}@media(max-width:700px){.display{padding:16px}.timer{font-size:24vw}.hero{min-height:50vh}.next{gap:2rem}}
</style>